import app from 'flarum/admin/app';
import AdminPage from 'flarum/admin/components/AdminPage';
import SettingsPreview from './component/SettingsPreview';
import Embed from '../common/models/Embed';

app.initializers.add('kilowhat-rich-embeds', () => {
    app.store.models['kilowhat-rich-embeds'] = Embed;

    app.extensionData
        .for('kilowhat-rich-embeds')
        .registerSetting(function (this: AdminPage) {
            return m(SettingsPreview, {
                layout: this.setting('kilowhat-rich-embeds.layout')(),
                style: this.setting('kilowhat-rich-embeds.style')(),
                withoutOpengraph: !!this.setting('kilowhat-rich-embeds.withoutOpengraph')(),
            });
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.layout',
            type: 'select',
            options: {
                inline: app.translator.trans('kilowhat-rich-embeds.admin.settings.layoutOptions.inline'),
                block: app.translator.trans('kilowhat-rich-embeds.admin.settings.layoutOptions.block'),
                separated: app.translator.trans('kilowhat-rich-embeds.admin.settings.layoutOptions.separated'),
            },
            default: 'block',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.layout'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.style',
            type: 'select',
            options: {
                vertical: app.translator.trans('kilowhat-rich-embeds.admin.settings.styleOptions.vertical'),
                horizontal: app.translator.trans('kilowhat-rich-embeds.admin.settings.styleOptions.horizontal'),
            },
            default: 'vertical',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.style'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.maxImageCount',
            type: 'number',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.maxImageCount'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.maxImageCountHelp'),
            placeholder: app.translator.trans('kilowhat-rich-embeds.admin.settings.maxImageCountPlaceholder'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.imageProxy',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.imageProxy'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.imageProxyHelp'),
        })
        /*.registerSetting({
            setting: 'kilowhat-rich-embeds.cacheProxy',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.cacheProxy'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.cacheProxyHelp'),
        })*/
        .registerSetting({
            setting: 'kilowhat-rich-embeds.withoutOpengraph',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.withoutOpengraph'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.withoutOpengraphHelp'),
        })
        .registerSetting(function (this: AdminPage) {
            return m('.Form-group', [
                m('label', app.translator.trans('kilowhat-rich-embeds.admin.settings.blacklist')),
                m('.helpText', app.translator.trans('kilowhat-rich-embeds.admin.settings.blacklistHelp')),
                m('textarea.FormControl', {
                    bidi: this.setting('kilowhat-rich-embeds.blacklist'),
                }),
            ]);
        })
        .registerSetting(function (this: AdminPage) {
            return m('.Form-group', [
                m('label', app.translator.trans('kilowhat-rich-embeds.admin.settings.whitelist')),
                m('.helpText', app.translator.trans('kilowhat-rich-embeds.admin.settings.whitelistHelp')),
                m('textarea.FormControl', {
                    bidi: this.setting('kilowhat-rich-embeds.whitelist'),
                }),
            ]);
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.imageEmbeds',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.imageEmbeds'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.imageEmbedsHelp'),
        })
        .registerSetting(() => m('p.rich-embeds-site-specific.helpText', app.translator.trans('kilowhat-rich-embeds.admin.section.siteSpecificHelp')))
        .registerSetting(() => m('h3.rich-embed-site-section', app.translator.trans('kilowhat-rich-embeds.admin.section.flarum')))
        .registerSetting({
            setting: 'kilowhat-rich-embeds.flarumApiPreviews',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.flarumApiPreviews'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.flarumApiPreviewsHelp'),
        })
        .registerSetting(() => m('h3.rich-embed-site-section', app.translator.trans('kilowhat-rich-embeds.admin.section.github')))
        .registerSetting({
            setting: 'kilowhat-rich-embeds.githubApiKey',
            type: 'text',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.githubApiKey'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.githubApiKeyHelp'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.githubOrgWhitelist',
            type: 'text',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.githubOrgWhitelist'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.githubOrgWhitelistHelp'),
        })
        .registerSetting(() => m('h3.rich-embed-site-section', app.translator.trans('kilowhat-rich-embeds.admin.section.google')))
        .registerSetting({
            setting: 'kilowhat-rich-embeds.googleApiKey',
            type: 'text',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.googleApiKey'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.googleApiKeyHelp'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.googleApiAuthConfig',
            type: 'textarea',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.googleApiAuthConfig'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.googleApiAuthConfigHelp'),
        })
        .registerSetting(() => m('h3.rich-embed-site-section', app.translator.trans('kilowhat-rich-embeds.admin.section.youtube')))
        .registerSetting({
            setting: 'kilowhat-rich-embeds.youtubePlayer',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.youtubePlayer'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.youtubePlayerHelp'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.youtubeNoCookie',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.youtubeNoCookie'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.youtubeNoCookieHelp'),
        })
        .registerSetting({
            setting: 'kilowhat-rich-embeds.youtubeApiPreviews',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.youtubeApiPreviews'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.youtubeApiPreviewsHelp'),
        })
        .registerSetting(() => m('h3.rich-embed-site-section', app.translator.trans('kilowhat-rich-embeds.admin.section.googledrive')))
        .registerSetting({
            setting: 'kilowhat-rich-embeds.googledriveApiPreviews',
            type: 'switch',
            label: app.translator.trans('kilowhat-rich-embeds.admin.settings.googledriveApiPreviews'),
            help: app.translator.trans('kilowhat-rich-embeds.admin.settings.googledriveApiPreviewsHelp'),
        })
        .registerPermission({
            icon: 'fas fa-book',
            label: app.translator.trans('kilowhat-rich-embeds.admin.permissions.viewGoogleDriveThumbnails'),
            permission: 'kilowhat-rich-embeds.viewGoogleDriveThumbnails',
            allowGuest: true,
        }, 'view')
        .registerPermission({
            icon: 'fas fa-book',
            label: app.translator.trans('kilowhat-rich-embeds.admin.permissions.useOnOwnPost'),
            permission: 'kilowhat-rich-embeds.useOnOwnPost',
        }, 'reply')
        .registerPermission({
            icon: 'fas fa-book',
            label: app.translator.trans('kilowhat-rich-embeds.admin.permissions.disableOnOwnPost'),
            permission: 'kilowhat-rich-embeds.disableOnOwnPost',
        }, 'reply')
        .registerPermission({
            icon: 'fas fa-book',
            label: app.translator.trans('kilowhat-rich-embeds.admin.permissions.disableOnAnyPost'),
            permission: 'kilowhat-rich-embeds.disableOnAnyPost',
        }, 'moderate')
        .registerPermission({
            icon: 'fas fa-book',
            label: app.translator.trans('kilowhat-rich-embeds.admin.permissions.refreshOnAnyPost'),
            permission: 'kilowhat-rich-embeds.refreshOnAnyPost',
        }, 'moderate');
});
