import {ClassComponent, Vnode} from 'mithril';
import app from 'flarum/admin/app';
import saveSettings from 'flarum/admin/utils/saveSettings';
import {ApiPayloadSingle} from 'flarum/common/Store';
import Button from 'flarum/common/components/Button';
import RichEmbed from '../../common/components/RichEmbed';
import Embed from '../../common/models/Embed';

interface SettingsPreviewAttrs {
    layout: string
    style: string
    withoutOpengraph: boolean
}

export default class SettingsPreview implements ClassComponent<SettingsPreviewAttrs> {
    urlEdit!: string
    url!: string
    loading: boolean = true
    embed?: Embed

    oninit() {
        this.urlEdit = app.data.settings['kilowhat-rich-embeds.previewUrl'] || 'https://github.com/flarum/framework';
        this.url = this.urlEdit;

        this.refresh();
    }

    view(vnode: Vnode<SettingsPreviewAttrs, this>) {
        const labelHtmlCast = document.createElement('div');
        labelHtmlCast.textContent = this.url;

        return m('.rich-embed-settings-preview', [
            m('h3', app.translator.trans('kilowhat-rich-embeds.admin.preview.title')),
            m('.rich-embed-settings-group', [
                m('input.FormControl', {
                    value: this.urlEdit,
                    oninput: (event: InputEvent) => {
                        this.urlEdit = (event.target as HTMLInputElement).value;
                    },
                }),
                Button.component({
                    className: 'Button',
                    icon: this.loading ? 'fas fa-spinner fa-pulse' : 'fas fa-sync',
                    onclick: () => {
                        this.loading = true;

                        saveSettings({
                            'kilowhat-rich-embeds.previewUrl': this.urlEdit,
                        }).then(() => {
                            this.url = this.urlEdit;
                            this.refresh();
                        });
                    },
                }, app.translator.trans('kilowhat-rich-embeds.admin.preview.refresh')),
            ]),
            m('a.rich-embed', {
                href: this.url,
            }, this.embed ? m(RichEmbed, {
                layout: vnode.attrs.layout,
                style: vnode.attrs.style,
                withoutOpengraph: vnode.attrs.withoutOpengraph,
                labelHtml: labelHtmlCast.innerHTML,
                embed: this.embed,
                canDisable: false,
                disable: () => Promise.resolve(),
            }) : app.translator.trans('kilowhat-rich-embeds.admin.preview.loading')),
        ]);
    }

    refresh() {
        app.request<ApiPayloadSingle>({
            method: 'POST',
            url: app.forum.attribute('apiUrl') + '/kilowhat-rich-embeds/get',
            body: {
                url: this.url,
            },
        }).then(response => {
            this.embed = app.store.pushPayload<Embed>(response);

            this.loading = false;

            m.redraw();
        }).catch(error => {
            this.loading = false;
            m.redraw();

            throw error;
        });
    }
}
